parameters.text:
=You are a strict QA Compliance Evaluator for an Insurance RAG System.

USER QUERY:
{{ $json.user_query }}

AGENT RESPONSE TO EVALUATE:
{{ $json.agent_output }}

EVALUATION RULES:
1. PASS CONDITION ("pass": true): The response MUST contain explicit insurance policy facts, numerical values, clause references, or specific terms (e.g., waiting periods, depreciation %, IMT codes, cover limits) retrieved from the database.
2. FAIL CONDITION ("pass": false): If the response contains any fallback disclaimer (e.g., "Information not found", "consult customer support"), refusals, small talk, or general non-policy answers, it is INVALID ("pass": false).

Output ONLY valid JSON:
- If valid policy facts are present:
  {"score": 5, "pass": true, "reasoning": "Response contains verified policy clauses."}
- If fallback text, refusal, or missing policy context:
  {"score": 1, "pass": false, "reasoning": "Response contains fallback disclaimer or lacks retrieved policy context."}

parameters.jsCode:
// Extract incoming LLM evaluation output safely in 'Run Once for Each Item' mode
const inputJson = $json || {};
const rawText = inputJson.text || inputJson.output || inputJson.message?.content || (typeof inputJson === 'string' ? inputJson : JSON.stringify(inputJson));

let parsedEval = {};

try {
  // Strip markdown code fences if present
  const cleanedText = String(rawText).replace(/```json/g, '').replace(/```/g, '').trim();
  parsedEval = JSON.parse(cleanedText);
} catch (e) {
  // Safe fallback if JSON parsing fails
  parsedEval = {
    score: 1,
    pass: false,
    reasoning: "Failed to parse evaluator JSON response."
  };
}

return {
  score: Number(parsedEval.score) || 1,
  pass: String(parsedEval.pass).toLowerCase() === 'true',
  reasoning: parsedEval.reasoning || "No reasoning provided."
};

// Get user query safely from the Chat Trigger
const userQuery = $('When chat message received').first()?.json?.chatInput || '';

// Get output safely from the AI Agent node
const agentOutput = $input.item?.json?.output || $input.item?.json?.text || '';

return {
  json: {
    user_query: userQuery,
    agent_output: agentOutput,
    eval_timestamp: new Date().toISOString()
  }
};

// Preserve original chat input and set initial retry count
const inputData = $input.first()?.json || {};
const chatInput = inputData.chatInput || inputData.query || '';

return {
  json: {
    user_query: chatInput,
    current_query: chatInput,
    retry_count: 0
  }
};

// Incoming item from Query Reformulator
const inputJson = $input.first()?.json || {};
const newQuery = inputJson.text || inputJson.output || '';

// Safely pull state from upstream evaluation nodes
const payloadData = $('Payload Assembler').first()?.json || {};
const evalData = $('LLM Chain Evaluator').first()?.json || {};

const userQuery = payloadData.user_query || '';
const currentRetries = payloadData.retry_count || 0;

return {
  json: {
    user_query: userQuery,
    current_query: newQuery || userQuery,
    retry_count: currentRetries + 1,
    last_reasoning: evalData.reasoning || ''
  }
};
